package ke.co.bethanyhouse.neema.feature.overview

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp
import ke.co.bethanyhouse.neema.core.ui.theme.WebIcons

/**
 * The exact shapes OverviewView.tsx draws: the stat cards' STAT_ICONS
 * (heroicons, stroked 1.8) and lib/channels.tsx's brand glyphs for the
 * By Channel panel. Generated from the web sources.
 */
internal object OverviewIcons {
    private fun build(name: String, filled: Boolean, width: Float, vararg paths: String): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
            paths.forEach { d ->
                addPath(
                    pathData = addPathNodes(WebIcons.expandArcFlags(d)),
                    fill = if (filled) SolidColor(Color.Black) else null,
                    stroke = if (filled) null else SolidColor(Color.Black),
                    strokeLineWidth = width,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round,
                )
            }
        }.build()

