    /** lib/channels.tsx CHANNEL_CONFIG[ch].icon; null for a channel the web has no config for. */
    fun channel(ch: String): ImageVector? = when (ch) {
        "whatsapp" -> WhatsApp
        "messenger" -> Messenger
        "facebook" -> Facebook
        "instagram" -> Instagram
        "tiktok" -> TikTok
        "email" -> Email
        "sms" -> Sms
